    // nested child object on the wire must decode into a TreeNode instance,
    // not be left as a raw plain object, so the recursion is honoured all
    // the way down. The leaf's own child is absent and must stay null.
    const json = { value: "root", child: { value: "leaf" } };
    const top = ObjectSerializer.deserialize(json, TreeNode);
    expect(top).toBeDefined();
    expect(top!.value).toBe("root");
