  describe("ByteArrayBufferRoundTrip (2.1)", () => {
    // 2.1 — `format: byte` values round-trip Buffer <-> base64 string at
    // the serde boundary. The model holds Buffer; the wire holds base64.

    test("bhv serialization 063 serialize: Buffer field encodes to base64 in the wire payload", () => {
      const passport = new PetPassport({
        thumbnail: Buffer.from(
          "hello-world",
          "utf-8",
        ) as unknown as PetPassport["thumbnail"],
      });
      const json = ObjectSerializer.serialize(passport);
      const parsed = JSON.parse(json) as Record<string, unknown>;
      expect(parsed["thumbnail"]).toBe(
        Buffer.from("hello-world", "utf-8").toString("base64"),
      );
    });

    test("bhv serialization 062 deserialize: base64 string on the wire decodes to a Buffer field", () => {
      const wire = {
        thumbnail: Buffer.from("round-trip", "utf-8").toString("base64"),
      };
      const passport = ObjectSerializer.deserialize(wire, PetPassport);
      expect(passport).toBeDefined();
      expect(Buffer.isBuffer((passport as PetPassport).thumbnail)).toBe(true);
      expect(
        ((passport as PetPassport).thumbnail as unknown as Buffer).toString(
          "utf-8",
        ),
      ).toBe("round-trip");
    });

    test("bhv serializationobject 094 deserialize: an invalid base64 thumbnail is rejected, not silently truncated", () => {
      // '!!!!' is outside the base64 alphabet. Buffer.from would silently yield
      // empty bytes; decodeBase64 must reject it, matching the strict decoders
      // in ruby/php/python/elixir/go/rust.
      expect(() =>
        ObjectSerializer.deserialize({ thumbnail: "!!!!" }, PetPassport),
      ).toThrow();
    });

    test.each(["dGVzdA", "dGVz dA==", "dGVz\ndA==", "-_8=", "!!!!"])(
      "deserialize: non-canonical base64 %p is rejected with SerializationError",
      (thumbnail) => {
        expect(() =>
          ObjectSerializer.deserialize({ thumbnail }, PetPassport),
        ).toThrow(SerializationError);
      },
    );

    test("bhv serializationobject 207 a non-standard base64 value is rejected on decode", () => {
      for (const thumbnail of [
        "dGVzdA",
        "dGVz dA==",
        "dGVz\ndA==",
        "-_8=",
        "!!!!",
      ]) {
        expect(() =>
          ObjectSerializer.deserialize({ thumbnail }, PetPassport),
        ).toThrow(SerializationError);
      }
    });

    test("bhv serializationobject 185 deserialize: canonical padded base64 is accepted", () => {
      const passport = ObjectSerializer.deserialize(
        { thumbnail: "dGVzdA==" },
        PetPassport,
      );
      expect(
        ((passport as PetPassport).thumbnail as unknown as Buffer).toString(
          "utf-8",
        ),
      ).toBe("test");
    });

    test("bhv serializationobject 156 stringify: bytes become standard padded base64", () => {
      expect(ObjectSerializer.stringify(Buffer.from("hi", "utf-8"))).toBe(
        "aGk=",
      );
      expect(ObjectSerializer.stringify(new Uint8Array([0xfb, 0xff]))).toBe(
        "+/8=",
      );
    });

    test("bhv serializationobject 026 bhv serializationobject 079 round-trip: serialize then deserialize preserves the Buffer bytes", () => {
      const original = Buffer.from([0x00, 0x01, 0xff, 0xee, 0xab]);
      const passport = new PetPassport({
        thumbnail: original as unknown as PetPassport["thumbnail"],
      });
      const json = ObjectSerializer.serialize(passport);
      const restored = ObjectSerializer.deserialize(
        JSON.parse(json),
        PetPassport,
      );
      expect(restored).toBeDefined();
      expect(
        Buffer.compare(
          (restored as PetPassport).thumbnail as unknown as Buffer,
          original,
        ),
      ).toBe(0);
    });

    test("a non-Buffer, non-string thumbnail is built without complaint and rejected when decoded", () => {
      expect(
        () =>
          new PetPassport({
            thumbnail: 42 as unknown as PetPassport["thumbnail"],
          }),
      ).not.toThrow();
      expect(() =>
        ObjectSerializer.deserialize({ thumbnail: 42 }, PetPassport),
      ).toThrow(SerializationError);
    });
  });

